import { useId } from "react";
import { SITE } from "@/lib/site";
import { DOODLES, lightSvg, PILLS, sceneSvg, type LightState, type SceneOptions } from "@/lib/kit/art";

// Server-rendered wrappers around the illustration kit. The SVG strings are generated by our own
// code from fixed data, so injecting them as HTML is safe.

export function Scene({ name, className = "", ...opts }: { name: string; className?: string } & SceneOptions) {
  return <div className={`art ${className}`} dangerouslySetInnerHTML={{ __html: sceneSvg(name, opts) }} />;
}

export function Light({ size = 96, state = "idle", label = SITE.name }: { size?: number; state?: LightState; label?: string }) {
  const id = useId();
  return (
    <span
      className="light"
      style={{ "--s": `${size}px` } as React.CSSProperties}
      data-state={state}
      // label="" marks a decorative Light (next to a visible name, or inside a bigger picture)
      role={label ? "img" : undefined}
      aria-label={label || undefined}
      aria-hidden={label ? undefined : true}
      dangerouslySetInnerHTML={{ __html: lightSvg(id) }}
    />
  );
}

// A landscape scene with the Light shining in it, standing in for the sun or moon. x and y place the centre of the
// sphere, in % of the picture; size is the Light's width as a share of the picture's height.
export function LightScene({
  name,
  state = "idle",
  x = 72,
  y = 34,
  size = 0.62,
  className = "",
  label,
}: {
  name: string;
  state?: LightState;
  x?: number;
  y?: number;
  size?: number;
  className?: string;
  label?: string;
}) {
  return (
    <div className={`art light-scene ${className}`} role={label ? "img" : undefined} aria-label={label} aria-hidden={label ? undefined : true}>
      <div dangerouslySetInnerHTML={{ __html: sceneSvg(name, { noSun: true }) }} />
      <span className="ls-light" style={{ left: `${x}%`, top: `${y}%`, "--k": size } as React.CSSProperties}>
        <Light size={96} state={state} label="" />
      </span>
    </div>
  );
}

// A headline picture pill where the Light acts out the words around it (PILLS in lib/kit/art.ts)
export function MascotPill({ art, className = "" }: { art: keyof typeof PILLS; className?: string }) {
  const p = PILLS[art];
  const svg = (layer: string) =>
    `<svg viewBox="0 0 160 100" preserveAspectRatio="xMidYMid slice" aria-hidden="true">${layer}</svg>`;
  return (
    <span className={`art light-scene mascot-pill ${className}`} aria-hidden>
      <span className="mp-layer" dangerouslySetInnerHTML={{ __html: svg(p.bg) }} />
      <span className="ls-light" style={{ left: `${p.light.x}%`, top: `${p.light.y}%`, "--k": p.light.size } as React.CSSProperties}>
        <Light size={96} state={p.light.state} label="" />
      </span>
      <span className="mp-layer fg" dangerouslySetInnerHTML={{ __html: svg(p.fg) }} />
    </span>
  );
}

// "holy hush" with the Light as the "o"; sized by the surrounding font-size
export function Wordmark({ className = "" }: { className?: string }) {
  return (
    <span className={`wordmark-lo ${className}`} role="img" aria-label={SITE.name}>
      <span aria-hidden>h</span>
      <span className="wm-o" aria-hidden>
        <Light size={100} label="" />
      </span>
      <span aria-hidden>ly hush</span>
    </span>
  );
}

export function Doodle({ name, className = "" }: { name: keyof typeof DOODLES; className?: string }) {
  return <div className={className} dangerouslySetInnerHTML={{ __html: DOODLES[name] }} />;
}

const icon = (d: React.ReactNode, size: number, stroke: number) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={stroke} strokeLinecap="round" strokeLinejoin="round" aria-hidden>
    {d}
  </svg>
);

export const ArrowIcon = ({ size = 20 }: { size?: number }) => icon(<path d="M5 12h14M13 6l6 6-6 6" />, size, 2.4);
export const CheckIcon = ({ size = 16 }: { size?: number }) => icon(<path d="M5 12.5l4.5 4.5L19 7.5" />, size, 3);
export const BookIcon = ({ size = 14 }: { size?: number }) =>
  icon(<path d="M2 4h6a4 4 0 014 4v13a3 3 0 00-3-3H2zM22 4h-6a4 4 0 00-4 4v13a3 3 0 013-3h7z" />, size, 2);
